import{_ as e,o as i,a,b as r}from"./app.C41L12d5.js";const o="/ascendc.github.io/assets/calc_tail.BEClJe_F.png",_="/ascendc.github.io/assets/core_load_balance.CQWSbLP3.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子性能优化","link":"/guide/operator_practice/simd_operator_optimization/simd_operator_optimization"},{"text":"Tiling策略","link":"/guide/operator_practice/simd_operator_optimization/tiling_strategy/tiling_strategy"},{"text":"核间负载均衡","link":"/guide/operator_practice/simd_operator_optimization/tiling_strategy/inter_core_load_balance"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_optimization/tiling_strategy/inter_core_load_balance.md","filePath":"guide/operator_practice/simd_operator_optimization/tiling_strategy/inter_core_load_balance.md","lastUpdated":1786954352000}'),n={name:"guide/operator_practice/simd_operator_optimization/tiling_strategy/inter_core_load_balance.md"};function p(s,t,c,l,d,g){return i(),a("div",null,[...t[0]||(t[0]=[r('<div><article class="markdown-body"><h1>核间负载均衡<span id="ZH-CN_TOPIC_0000001892919393"></span></h1><p>【优先级】：中</p><p>【描述】AI处理器的物理核数是固定的，当L2 Cache切分之后，可能发生部分核有计算拖尾的情况，即每次所有核计算量除以每个核处理的数据量不能被核数整除，导致最后需要部分尾核来计算尾块数据。而在尾核计算时，部分核始终处于空闲状态，从而使得算子的整体性能变差。如<a href="#fig26395321518">图1</a>，假设总的数据量为TotalSize，L2 Cache切分之后分为两份TotalSize / 2，每个核每次的计算量为TotalSize / 2 / 25，即需要25个核进行处理，由于AI处理器的核数为20，因此每次计算时，1到5核的每个核需要多算一份数据，导致发生拖尾的情况。</p><p>更详细的多核Tiling切分过程请参见<a href="../../simd_operator_impl/vector_programming/multi_core_tiling/overview.html">多核Tiling切分</a>。</p><p>【反例】</p><p><strong>图1</strong> 计算拖尾示意图<span id="fig26395321518"></span><br><img src="'+o+'" alt title="计算拖尾示意图"></p><p>【正例】</p><p>针对上述切分策略，调整拖尾核的位置后可以达到全局负载最优，如<a href="#fig133658471154">图2</a>所示。完成所有计算时，1到10核多一次数据块的计算，可以实现全局负载最优。</p><p><strong>图2</strong> 核间负载均衡示意图<span id="fig133658471154"></span><br><img src="'+_+'" alt title="核间负载均衡示意图"></p></article></div>',1)])])}const b=e(n,[["render",p]]);export{u as __pageData,b as default};
